let enrolmentDraft=null,enrolmentValues=null,enrolmentBusy=false;const el=id=>document.getElementById(id);const raceNames={Unimatrix999World:'Unimatrix999 Sovereign',SilverWorld:'Silver Registry',BorgWorld:'Unimatrix Sovereign',UndineWorld:'Fluidic Dominion',LegendaryWorld:'Imperial Legend',UltimateWorld:'Arrakis Ascendant',Terran:'Helion',Cathaar:'Velari',Xandathrii:'Nexari',Zikonian:'Kryth',Eitraides:'Auralis',AstraNexus:'Astra Nexus',LCARS:'Stellar Federation',Borg:'Assimilation Nexus',Stargate:'Gatebound Legacy',DoctorWho:'Temporal Voyager',Battlestar:'Colonial Vanguard'};async function enrolmentRequest(body){const r=await fetch('/api/planet-enrolment',{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'Registration unavailable.');return d;}async function loadEnrolment(){try{enrolmentDraft=await enrolmentRequest();if(enrolmentDraft.confirmed){location.replace('/game');return;}const t=enrolmentDraft.planetType;el('stats').replaceChildren();el('reroll').disabled=!enrolmentDraft.rerollsRemaining;el('reroll').textContent='REROLL WORLD · '+enrolmentDraft.rerollsRemaining+' / 3 LEFT';el('typeName').textContent=t.name+' · '+t.rarity;el('planetArtwork').src='/assets/planets/'+t.id+'.svg';el('planetArtwork').alt=t.name+' orbital survey';el('lore').textContent=t.lore;const stats=[['Habitability',t.habitability+'%'],['Biodiversity',t.biodiversity+'%'],['Moisture',t.moisture+'%'],['Rockiness',t.rockiness+'%'],['Starting residents',t.basePopulation.toLocaleString()],['Growth modifier',(t.growthPercent>=0?'+':'')+t.growthPercent+'%'],['Mining bonus','+'+(t.basePopulation*.001).toFixed(3)+'%'],['CU / RP bonus','+'+Math.floor(t.basePopulation/100)],['Housing',t.basePopulation.toLocaleString()]];for(const [label,value] of stats){const box=document.createElement('div'),small=document.createElement('small'),b=document.createElement('b');small.textContent=label;b.textContent=value;box.append(small,b);el('stats').append(box);}el('ruler').value=enrolmentDraft.username;el('planetName').value=t.canonicalName||enrolmentDraft.username+"'s planet";el('planetName').readOnly=!!t.canonicalName;for(const kind of ['race','theme']){el(kind).replaceChildren();for(const v of enrolmentDraft[kind==='race'?'races':'themes']){const o=document.createElement('option');o.value=v;o.textContent=raceNames[v]||v;el(kind).append(o);}}if(t.theme){el('theme').value=t.theme;document.body.dataset.skin=t.theme;}el('content').hidden=false;el('loading').hidden=true;}catch(e){el('loading').textContent=e.message;}}
el('charter').addEventListener('submit',e=>{e.preventDefault();enrolmentValues={ruler:el('ruler').value.trim(),planetName:el('planetName').value.trim(),race:el('race').value,theme:el('theme').value,generation:enrolmentDraft.generation,planetType:enrolmentDraft.planetType.id,confirmation:true};el('reviewValues').replaceChildren();for(const [label,value] of [['Ruler',enrolmentValues.ruler],['Planet',enrolmentValues.planetName],['Race',raceNames[enrolmentValues.race]],['Theme',raceNames[enrolmentValues.theme]||enrolmentValues.theme],['Planet type',enrolmentDraft.planetType.name],['Starting population',enrolmentDraft.planetType.basePopulation]]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;el('reviewValues').append(dt,dd);}const world=enrolmentDraft.planetType;el('confirmWorldName').textContent=world.name;el('confirmWorldArtwork').src='/assets/planets/'+world.id+'.svg';el('confirmWorldArtwork').alt=world.name+' orbital survey';el('confirmWorldLore').textContent=world.lore;el('confirmWorldStats').replaceChildren();for(const [label,value] of [['Habitability',world.habitability+'%'],['Biodiversity',world.biodiversity+'%'],['Moisture',world.moisture+'%'],['Rockiness',world.rockiness+'%'],['Starting residents',world.basePopulation.toLocaleString()],['Growth modifier',(world.growthPercent>=0?'+':'')+world.growthPercent+'%'],['Mining bonus','+'+(world.basePopulation*.001).toFixed(3)+'%'],['CU / RP bonus','+'+Math.floor(world.basePopulation/100)],['Housing',world.basePopulation.toLocaleString()]]){const box=document.createElement('div'),small=document.createElement('small'),b=document.createElement('b');small.textContent=label;b.textContent=value;box.append(small,b);el('confirmWorldStats').append(box);}el('confirmation').showModal();});el('back').onclick=()=>el('confirmation').close();el('enter').onclick=async()=>{if(enrolmentBusy)return;enrolmentBusy=true;el('enter').disabled=true;try{const confirmed=await enrolmentRequest(enrolmentValues);enrolmentValues.theme=confirmed.theme;localStorage.setItem('starfall-enrolment-theme',enrolmentValues.theme);location.replace('/game');}catch(e){el('confirmError').textContent=e.message;enrolmentBusy=false;el('enter').disabled=false;}};loadEnrolment();

el('theme').addEventListener('change',()=>{document.body.dataset.skin=el('theme').value;});
el('reroll').onclick=async()=>{if(enrolmentBusy||!enrolmentDraft.rerollsRemaining)return;enrolmentBusy=true;el('reroll').disabled=true;try{await enrolmentRequest({action:'reroll',generation:enrolmentDraft.generation});await loadEnrolment();el('error').textContent='';}catch(e){el('error').textContent=e.message;}finally{enrolmentBusy=false;el('reroll').disabled=!enrolmentDraft.rerollsRemaining;}};
